// PlayVerse expansion library — the 86 original games added to reach the
// 100-game catalog, plus full-length page content for the original 14.
// Every entry describes only mechanics actually implemented in the client
// player (client/src/games2.tsx … games5.tsx). Content is written per game:
// description (introduction), instructions (how to play), rules, tips,
// features and FAQs together land in the 400–500 word range per page.

export type GameContent = {
  description: string;
  instructions: string;
  rules: string;
  tips: string[];
  features: string[];
  faqs: { q: string; a: string }[];
};

export type LibraryGame = GameContent & {
  title: string;
  slug: string;
  builtinKey: string;
  emoji: string;
  c1: string;
  c2: string;
  category: string; // primary category slug — the game's one category link
  controls: Record<string, string>;
  featured?: boolean;
  trending?: boolean;
  isNew?: boolean;
};

